// CampaignMessages is the resolver for the campaignMessages field.
func (r *subscriptionResolver) CampaignMessages(ctx context.Context, campaignID string) (<-chan *model.Message, error) {
	uuid, err := parseUUID("campaign", campaignID)
	if err != nil {
		return nil, err
	}

	_, user, err := r.loadCampaign(ctx, uuid, false)
	if err != nil {
		return nil, err
	}

	rows, err := r.Broker.Subscribe(ctx, uuid)
	if err != nil {
		return nil, fmt.Errorf("failed to subscribe to campaign with ID '%s': %w", campaignID, err)
	}

	out := make(chan *model.Message, 1)
	go func() {
		defer close(out)

		for row := range rows {
			message, err := r.deliverable(ctx, &row, user)
			if err != nil {
				slog.ErrorContext(ctx, "failed to deliver a chat message", "id", row.ID.String(), "error", err)
				return
			}
			if message == nil {
				continue
			}

			select {
			case out <- message:
			case <-ctx.Done():
				return
			}
		}
	}()

	return out, nil
}

